def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            x = value[0]
            y = value[1]
            if isinstance(x, int) and isinstance(y, int):
                return x, y
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = corners[0]
        best_score = None
        for c in corners:
            score = dist(c, opp_pos)
            if best_score is None or score > best_score:
                best_score = score
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        best_score = None
        for t in targets:
            tp = pos(t, None)
            if tp is None:
                continue
            score = dist(self_pos, tp)
            if best_score is None or score < best_score:
                best_score = score
                best = tp
        if best is not None:
            return step_toward(self_pos, best)

        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        center = (gw // 2, gh // 2) if gw and gh else (sx + 1, sy + 1)
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for r in resources:
        rp = pos(r, None)
        if rp is None:
            continue
        score = dist(self_pos, rp)
        if "pursuit_evasion" not in env:
            score -= dist(opp_pos, rp) * 0.25
        if best_score is None or score < best_score:
            best_score = score
            best = rp

    if best is not None:
        return step_toward(self_pos, best)

    return step_away(self_pos, opp_pos)

